348	// runExplainCheckpointJSON resolves a single checkpoint and emits a metadata-only
349	// JSON envelope. Reads each session's metadata through the committed checkpoint
350	// reader; never reads any transcript file.
351	func runExplainCheckpointJSON(ctx context.Context, w, errW io.Writer, opts explainExportOptions) error {
352		cpID, lookup, err := resolveExplainCheckpointID(ctx, errW, opts)
353		if err != nil {
354			if lookup != nil {
355				_ = lookup.Close()
356			}
357			return err
358		}
359		defer lookup.Close()
360	
361		store := lookup.store
362		summary, err := checkpoint.ReadCheckpoint(ctx, store, cpID)
363		if err != nil {
364			return fmt.Errorf("failed to read checkpoint: %w", err)
365		}
366		if err := checkpointpolicy.EnsureCanReadVersion(cpID.String(), summary.CheckpointVersion); err != nil {
367			return err
368		}
369	
370		envelope, failedSessions := buildCheckpointJSONEnvelope(ctx, store, summary, cpID)
371	
372		enc := json.NewEncoder(w)
373		enc.SetIndent("", "  ")
374		if err := enc.Encode(envelope); err != nil {
375			return fmt.Errorf("failed to encode checkpoint json: %w", err)
376		}
377	
378		// Fail hard so automation can't mistake incomplete metadata for a clean
379		// export. The envelope (with its `partial` flag and per-session error
380		// fields) has already been written to stdout; using SilentError keeps
381		// the diagnostic on stderr from interleaving with that output.
382		if envelope.Partial {
383			fmt.Fprintf(errW, "checkpoint %s: failed to read metadata for %d session(s) (indexes %v)\n",
384				cpID, len(failedSessions), failedSessions)
385			return NewSilentError(fmt.Errorf("checkpoint %s export incomplete: %d session(s) unreadable", cpID, len(failedSessions)))
386		}
387		return nil
388	}
