390	// buildCheckpointJSONEnvelope builds the JSON envelope for a single checkpoint,
391	// reading each session's metadata via the supplied reader. Returns the envelope
392	// plus the list of session indexes that failed to read; a non-empty failed
393	// list means envelope.Partial is true. Extracted from runExplainCheckpointJSON so
394	// the envelope-building behavior can be tested independently of git storage.
395	func buildCheckpointJSONEnvelope(ctx context.Context, reader checkpoint.SessionReader, summary *checkpoint.CheckpointSummary, cpID id.CheckpointID) (checkpointExportJSON, []int) {
396		envelope := checkpointExportJSON{
397			CheckpointID:     cpID.String(),
398			Strategy:         summary.Strategy,
399			Branch:           summary.Branch,
400			CheckpointsCount: summary.CheckpointsCount,
401			FilesTouched:     summary.FilesTouched,
402			HasReview:        summary.HasReview,
403			HasInvestigation: summary.HasInvestigation,
404			SessionCount:     len(summary.Sessions),
405		}
406	
407		envelope.Sessions = make([]checkpointSessionJSON, 0, len(summary.Sessions))
408		var failedSessions []int
409		for idx := range summary.Sessions {
410			meta, metaErr := readSessionMetadataForExport(ctx, reader, cpID, idx)
411			if metaErr != nil {
412				// Surface the per-session error as a stub entry with an explicit
413				// error string rather than failing the whole envelope or silently
414				// returning empty fields. Consumers branch on the `error` field
415				// and the top-level `partial` flag.
416				envelope.Sessions = append(envelope.Sessions, checkpointSessionJSON{
417					Index: idx,
418					Error: metaErr.Error(),
419				})
420				failedSessions = append(failedSessions, idx)
421				continue
422			}
423			envelope.Sessions = append(envelope.Sessions, sessionMetadataToJSON(idx, meta))
424		}
425		envelope.Partial = len(failedSessions) > 0
426		return envelope, failedSessions
427	}
