490	// runExplainListJSON emits a JSON array of branch checkpoints, optionally
491	// filtered by session ID prefix (mirrors the prose list view). The cap
492	// defaults to branchCheckpointsLimit; pass listLimit > 0 to override.
493	//
494	// Truncation detection: we ask the underlying lister for one more than the
495	// effective cap. If we got that many back, we know there were at least
496	// `cap` checkpoints we didn't return — emit a stderr note so the consumer
497	// knows to set --limit higher. The JSON shape stays a flat array so jq
498	// pipelines don't have to unwrap.
499	func runExplainListJSON(ctx context.Context, w, errW io.Writer, sessionFilter string, listLimit int) error {
500		repo, err := openRepository(ctx)
501		if err != nil {
502			return fmt.Errorf("not a git repository: %w", err)
503		}
504		defer repo.Close()
505	
506		limit := listLimit
507		if limit <= 0 {
508			limit = branchCheckpointsLimit
509		}
510	
511		// Probe one extra so we can detect truncation.
512		points, err := getBranchCheckpoints(ctx, repo, limit+1)
513		if err != nil {
514			if ctx.Err() != nil {
515				return NewSilentError(ctx.Err())
516			}
517			// JSON consumers cannot distinguish "[]" from "fetch failed" if we
518			// swallow the error. Surface it so scripts get a non-zero exit and
519			// a real diagnostic instead of silently degraded output.
520			return fmt.Errorf("failed to list checkpoints: %w", err)
521		}
522		truncated := len(points) > limit
523		if truncated {
524			points = points[:limit]
525		}
526	
527		out := make([]branchCheckpointJSON, 0, len(points))
528		for _, p := range points {
529			if sessionFilter != "" && !checkpointMatchesSessionFilter(p, sessionFilter) {
530				continue
531			}
532			entry := branchCheckpointJSON{
533				SessionID:        p.SessionID,
534				Agent:            string(p.Agent),
535				Date:             p.Date,
536				Message:          p.Message,
537				IsTaskCheckpoint: p.IsTaskCheckpoint,
538				IsLogsOnly:       p.IsLogsOnly,
539				SessionCount:     p.SessionCount,
540				SessionIDs:       p.SessionIDs,
541			}
542			if !p.CheckpointID.IsEmpty() {
543				entry.CheckpointID = p.CheckpointID.String()
544			} else {
545				entry.CheckpointID = p.ID
546			}
547			out = append(out, entry)
548		}
549	
550		enc := json.NewEncoder(w)
551		enc.SetIndent("", "  ")
552		if err := enc.Encode(out); err != nil {
553			return fmt.Errorf("failed to encode checkpoint list: %w", err)
554		}
555	
556		if truncated {
557			fmt.Fprintf(errW, "note: list capped at %d checkpoints; rerun with --limit <N> to see more\n", limit)
558		}
559		return nil
560	}
